const COURSE_LESSON_HTML = {
  "kurssArticlesLesson": "\n  <h3>Artigos</h3>\n\n  <div class=\"artikuli-info artikuli-intro-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>O artigo alemão nem sempre coincide com o género da palavra em português. Por isso, é melhor aprender os substantivos juntamente com o artigo.</div>\n  </div>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>•</span>Exemplos de artigos</h4>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">der Tisch — mesa</div>\n      <div class=\"kurss-example\">die Tür — porta</div>\n      <div class=\"kurss-example\">das Messer — faca</div>\n      <div class=\"kurss-example\">das Mädchen — rapariga</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>♂</span>Frequentemente DER</h4>\n    <p class=\"artikuli-explain\">DER é frequentemente usado com pessoas do sexo masculino, dias, meses, estações do ano e algumas palavras com determinadas terminações.</p>\n\n    <h5 class=\"artikuli-subtitle\">Regras</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-er → frequentemente DER, por exemplo: der Computer, der Lehrer <span class=\"artikuli-note\">mas nem sempre</span></div>\n      <div class=\"kurss-example\">-ling → frequentemente DER, por exemplo: der Schmetterling</div>\n      <div class=\"kurss-example\">-ismus → frequentemente DER, por exemplo: der Tourismus, der Kapitalismus</div>\n      <div class=\"kurss-example\">pessoas do sexo masculino → der Mann, der Vater</div>\n      <div class=\"kurss-example\">profissões → der Lehrer, der Arzt</div>\n      <div class=\"kurss-example\">marcas de automóveis → der BMW, der Mercedes</div>\n      <div class=\"kurss-example\">dias → der Montag, der Dienstag</div>\n      <div class=\"kurss-example\">meses → der August, der Dezember</div>\n      <div class=\"kurss-example\">estações do ano → der Sommer, der Winter</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Exemplos</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">der Mann — homem</div>\n      <div class=\"kurss-example\">der Vater — pai</div>\n      <div class=\"kurss-example\">der Montag — segunda-feira</div>\n      <div class=\"kurss-example\">der August — agosto</div>\n      <div class=\"kurss-example\">der Sommer — verão</div>\n      <div class=\"kurss-example\">der Lehrer — professor</div>\n      <div class=\"kurss-example\">der Computer — computador</div>\n      <div class=\"kurss-example\">der Schmetterling — borboleta</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>♀</span>Frequentemente DIE</h4>\n    <p class=\"artikuli-explain\">DIE é frequentemente usado com pessoas do sexo feminino, o plural e palavras com as terminações -ung, -heit, -keit, -schaft, -ion, -tät, -ei.</p>\n\n    <h5 class=\"artikuli-subtitle\">Regras</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-ung → die Wohnung, die Rechnung</div>\n      <div class=\"kurss-example\">-heit → die Freiheit, die Gesundheit</div>\n      <div class=\"kurss-example\">-keit → die Möglichkeit</div>\n      <div class=\"kurss-example\">-schaft → die Mannschaft</div>\n      <div class=\"kurss-example\">-ion → die Nation</div>\n      <div class=\"kurss-example\">-tät → die Universität</div>\n      <div class=\"kurss-example\">-ei → die Polizei, die Bäckerei</div>\n      <div class=\"kurss-example\">pessoas do sexo feminino → die Frau, die Mutter</div>\n      <div class=\"kurss-example\">marcas de motas → die Harley-Davidson, die Yamaha</div>\n      <div class=\"kurss-example\">plural → die Autos, die Häuser</div>\n      <div class=\"kurss-example\">plural quase sempre → die Autos, die Häuser, die Kinder</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Exemplos</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">die Frau — mulher</div>\n      <div class=\"kurss-example\">die Mutter — mãe</div>\n      <div class=\"kurss-example\">die Wohnung — apartamento</div>\n      <div class=\"kurss-example\">die Rechnung — conta / fatura</div>\n      <div class=\"kurss-example\">die Freiheit — liberdade</div>\n      <div class=\"kurss-example\">die Möglichkeit — possibilidade</div>\n      <div class=\"kurss-example\">die Mannschaft — equipa</div>\n      <div class=\"kurss-example\">die Nation — nação</div>\n      <div class=\"kurss-example\">die Universität — universidade</div>\n      <div class=\"kurss-example\">die Polizei — polícia</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>◇</span>Frequentemente DAS</h4>\n    <p class=\"artikuli-explain\">DAS é frequentemente usado com diminutivos em -chen / -lein, muitas palavras em -ment / -um e verbos usados como substantivos.</p>\n\n    <h5 class=\"artikuli-subtitle\">Regras</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-chen → das Mädchen, das Häuschen</div>\n      <div class=\"kurss-example\">-lein → das Fräulein</div>\n      <div class=\"kurss-example\">-ment → das Instrument</div>\n      <div class=\"kurss-example\">-um → das Zentrum, das Museum</div>\n      <div class=\"kurss-example\">metais → das Gold, das Silber, das Eisen</div>\n      <div class=\"kurss-example\">elementos químicos → das Eisen, das Kupfer</div>\n      <div class=\"kurss-example\">hotéis → das Hotel</div>\n      <div class=\"kurss-example\">cores como substantivos → das Rot, das Blau</div>\n      <div class=\"kurss-example\">verbo como substantivo → das Essen, das Lernen</div>\n      <div class=\"kurss-example\">verbos como substantivos → das Essen, das Lernen, das Lesen</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Exemplos</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">das Kind — criança</div>\n      <div class=\"kurss-example\">das Mädchen — rapariga</div>\n      <div class=\"kurss-example\">das Häuschen — casinha</div>\n      <div class=\"kurss-example\">das Instrument — instrumento</div>\n      <div class=\"kurss-example\">das Zentrum — centro</div>\n      <div class=\"kurss-example\">das Museum — museu</div>\n      <div class=\"kurss-example\">das Essen — o comer / comida</div>\n      <div class=\"kurss-example\">das Lernen — aprendizagem</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>!</span>Exceções importantes / aprender com o artigo</h4>\n    <p class=\"artikuli-explain\">Em algumas palavras, o artigo não pode ser determinado com segurança pela terminação nem pelo género em português. É melhor aprendê-las juntamente com o artigo.</p>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">die Tür — porta</div>\n      <div class=\"kurss-example\">das Messer — faca</div>\n      <div class=\"kurss-example\">die Sonne — sol</div>\n      <div class=\"kurss-example\">der Mond — lua</div>\n      <div class=\"kurss-example\">das Mädchen — rapariga</div>\n      <div class=\"kurss-example\">das Auto — automóvel</div>\n      <div class=\"kurss-example\">der Käse — queijo</div>\n      <div class=\"kurss-example\">die Gabel — garfo</div>\n    </div>\n  </section>\n\n  <div class=\"artikuli-info artikuli-bottom-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>As terminações e os grupos de palavras ajudam a adivinhar o artigo, mas não são uma regra 100% segura. Se não tiveres a certeza, aprende a palavra juntamente com o artigo.</div>\n  </div>\n",
  "kurssPronounsLesson": "\n  <h3>Pronomes</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Nominativ, Akkusativ e Dativ — formas dos pronomes.</div>\n  </div>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>N</span>Nominativ — quem?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich — eu</div><div class=\"kurss-example\">du — tu</div><div class=\"kurss-example\">er — ele</div><div class=\"kurss-example\">sie — ela</div><div class=\"kurss-example\">es — ele / ela (neutro)</div><div class=\"kurss-example\">wir — nós</div><div class=\"kurss-example\">ihr — vocês</div><div class=\"kurss-example\">sie — eles / elas</div><div class=\"kurss-example\">Sie — o senhor / a senhora (formal)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>A</span>Akkusativ — o quê?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">mich — me</div><div class=\"kurss-example\">dich — te</div><div class=\"kurss-example\">ihn — o (m.)</div><div class=\"kurss-example\">sie — a (f.)</div><div class=\"kurss-example\">es — o / a</div><div class=\"kurss-example\">uns — nos</div><div class=\"kurss-example\">euch — vos</div><div class=\"kurss-example\">sie — os / as</div><div class=\"kurss-example\">Sie — o senhor / a senhora (formal)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>D</span>Dativ — a quem?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">mir — me</div><div class=\"kurss-example\">dir — te</div><div class=\"kurss-example\">ihm — lhe</div><div class=\"kurss-example\">ihr — lhe</div><div class=\"kurss-example\">uns — nos</div><div class=\"kurss-example\">euch — vos</div><div class=\"kurss-example\">ihnen — lhes</div><div class=\"kurss-example\">Ihnen — ao senhor / à senhora (formal)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>?</span>Como escolher a forma?</h4>\n    <ul class=\"kurss-summary-list\"><li><span class=\"case-blue\">Nominativ</span> — sujeito da frase (quem faz?)</li><li><span class=\"case-red\">Akkusativ</span> — complemento direto (o quê?)</li><li><span class=\"case-green\">Dativ</span> — complemento indireto (a quem?)</li></ul>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>•</span>Exemplos</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">Ich sehe <span class=\"case-red\">dich</span>. — Eu vejo-te.</div><div class=\"kurss-example\">Ich sehe <span class=\"case-red\">ihn</span>. — Eu vejo-o.</div><div class=\"kurss-example\">Wir mögen <span class=\"case-red\">euch</span>. — Nós gostamos de vocês.</div><div class=\"kurss-example\">Ich helfe <span class=\"case-green\">dir</span>. — Eu ajudo-te.</div><div class=\"kurss-example\">Ich gebe <span class=\"case-green\">ihm</span> ein Buch. — Eu dou-lhe um livro.</div><div class=\"kurss-example\">Wir danken <span class=\"case-green\">euch</span>. — Nós agradecemos-vos.</div></div>\n  </section>\n\n  <div class=\"artikuli-info artikuli-bottom-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>O Nominativ é sempre o sujeito da frase, e o Akkusativ e o Dativ são os complementos. Olha para o verbo e pergunta: <span class=\"case-red\">o quê?</span> ou <span class=\"case-green\">a quem?</span></div>\n  </div>\n",
  "kurssPronunciationLesson": "\n            <h3>Vogais — longas e curtas</h3>\n            <p class=\"kurss-lesson-intro\">Em alemão, as vogais podem ser longas ou curtas. Isso influencia a pronúncia da palavra.</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Vogal longa</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">warm (varm) — quente</div><div class=\"kurss-example\">gut (gūt) — bom</div><div class=\"kurss-example\">Tat (tāt) — ato / ação</div><div class=\"kurss-example\">Flur (flūr) — corredor</div><div class=\"kurss-example\">Weg (vēk) — caminho</div><div class=\"kurss-example\">Hut (hūt) — chapéu</div><div class=\"kurss-example\">Hof (hōf) — pátio / quinta</div><div class=\"kurss-example\">Schlaf (chlāf) — sono</div></div>\n              <p>Se a vogal for seguida de uma só consoante, a vogal é muitas vezes pronunciada longa.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Vogal curta</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Pilz (pilts) — cogumelo</div><div class=\"kurss-example\">Wort (vort) — palavra</div><div class=\"kurss-example\">Mund (munt) — boca</div><div class=\"kurss-example\">bald (balt) — em breve</div><div class=\"kurss-example\">scharf (charf) — afiado / picante</div><div class=\"kurss-example\">Feld (felt) — campo</div><div class=\"kurss-example\">voll (fol) — cheio</div></div>\n              <p>Se a vogal for seguida de duas ou mais consoantes, a vogal é muitas vezes pronunciada curta.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Terminações en / el / er</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">singen (zinguen) — cantar</div><div class=\"kurss-example\">tragen (trāguen) — levar / carregar</div><div class=\"kurss-example\">Garten (garten) — jardim</div><div class=\"kurss-example\">Vogel (fōguel) — pássaro / ave</div><div class=\"kurss-example\">Segel (zēguel) — vela (de barco)</div><div class=\"kurss-example\">Braten (brāten) — assado</div><div class=\"kurss-example\">Bogen (bōguen) — arco</div><div class=\"kurss-example\">Spiegel (chpīguel) — espelho</div><div class=\"kurss-example\">Finger (finguer) — dedo</div><div class=\"kurss-example\">Halter (halter) — suporte</div><div class=\"kurss-example\">Arbeiter (arbaiter) — trabalhador / operário</div><div class=\"kurss-example\">Häuser (hoizer) — casas</div><div class=\"kurss-example\">wieder (vīder) — outra vez / de novo</div><div class=\"kurss-example\">breiter (braiter) — mais largo</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>A letra h como sinal de vogal longa</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Rahmen (rāmen) — moldura</div><div class=\"kurss-example\">Ohr (ōr) — orelha / ouvido</div><div class=\"kurss-example\">Kohle (kōle) — carvão</div><div class=\"kurss-example\">Zahl (tsāl) — número</div><div class=\"kurss-example\">ihn (īn) — o / ele (complemento direto)</div><div class=\"kurss-example\">ihm (īm) — lhe / a ele</div><div class=\"kurss-example\">Huhn (hūn) — galinha</div><div class=\"kurss-example\">nahm (nām) — tomou / pegou</div><div class=\"kurss-example\">nehmen (nēmen) — tomar / pegar</div><div class=\"kurss-example\">Schuh (chū) — sapato</div></div>\n              <p>Em algumas palavras, o h alonga a vogal anterior. Nestes casos, o h normalmente não se pronuncia.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Terminações em e</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Lampe (lampe) — candeeiro / lâmpada</div><div class=\"kurss-example\">Hase (hāze) — lebre</div><div class=\"kurss-example\">Knabe (knābe) — rapaz</div><div class=\"kurss-example\">Rabe (rābe) — corvo</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>O i longo = ie</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">die (dī) — artigo «die»</div><div class=\"kurss-example\">diese (dīze) — esta / estes / estas</div><div class=\"kurss-example\">wieder (vīder) — outra vez / de novo</div><div class=\"kurss-example\">Fliege (flīgue) — mosca</div><div class=\"kurss-example\">Ziege (tsīgue) — cabra</div><div class=\"kurss-example\">Stiel (chtīl) — caule / cabo</div><div class=\"kurss-example\">Dieb (dīp) — ladrão</div><div class=\"kurss-example\">hier (hīr) — aqui</div></div>\n              <p>Em alemão, o i longo escreve-se muitas vezes ie.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Vogais duplas</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Saal (zāl) — sala / salão</div><div class=\"kurss-example\">Saat (zāt) — sementeira / semente</div><div class=\"kurss-example\">Staat (chtāt) — Estado</div><div class=\"kurss-example\">Beere (bēre) — baga</div><div class=\"kurss-example\">See (zē) — lago / mar</div><div class=\"kurss-example\">Beet (bēt) — canteiro</div><div class=\"kurss-example\">Boot (bōt) — barco</div><div class=\"kurss-example\">Moor (mōr) — pântano / turfeira</div><div class=\"kurss-example\">Moos (mōs) — musgo</div></div>\n              <p>As vogais duplas pronunciam-se normalmente longas.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ä</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Wand (vant) — parede</div><div class=\"kurss-example\">Wände (vende) — paredes</div><div class=\"kurss-example\">Vater (fāter) — pai</div><div class=\"kurss-example\">Väter (fēter) — pais</div><div class=\"kurss-example\">Schrank (chrank) — armário</div><div class=\"kurss-example\">Schränke (chrenke) — armários</div><div class=\"kurss-example\">Bank (bank) — banco</div><div class=\"kurss-example\">Bänke (benke) — bancos (assentos)</div><div class=\"kurss-example\">Tal (tāl) — vale</div><div class=\"kurss-example\">Täler (tēler) — vales</div></div>\n              <p>ä é a metafonia (Umlaut) de a.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ö</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Rose (rōze) — rosa</div><div class=\"kurss-example\">Röschen (rös-hen) — rosinha</div><div class=\"kurss-example\">Ofen (ōfen) — forno / fogão</div><div class=\"kurss-example\">Öfen (öfen) — fornos / fogões</div><div class=\"kurss-example\">Rock (rok) — saia</div><div class=\"kurss-example\">Röcke (röke) — saias</div></div>\n              <p>ö é a metafonia (Umlaut) de o.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ü</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">kurz (kurts) — curto</div><div class=\"kurss-example\">kürzer (kürtser) — mais curto</div><div class=\"kurss-example\">Kunst (kunst) — arte</div><div class=\"kurss-example\">Künste (künste) — artes</div><div class=\"kurss-example\">Mutter (muter) — mãe</div><div class=\"kurss-example\">Mütter (müter) — mães</div></div>\n              <p>ü é a metafonia (Umlaut) de u.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Ditongos: äu</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Baum (baum) — árvore</div><div class=\"kurss-example\">Bäume (boime) — árvores</div><div class=\"kurss-example\">Haus (haus) — casa</div><div class=\"kurss-example\">Häuser (hoizer) — casas</div><div class=\"kurss-example\">Strauch (chtrauh) — arbusto</div><div class=\"kurss-example\">Sträucher (chtroiher) — arbustos</div><div class=\"kurss-example\">Maus (maus) — rato</div><div class=\"kurss-example\">Mäuse (moize) — ratos</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Ditongos: eu</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">heute (hoite) — hoje</div><div class=\"kurss-example\">Leute (loite) — pessoas / gente</div><div class=\"kurss-example\">neu (noi) — novo</div><div class=\"kurss-example\">neun (noin) — nove</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Ditongos: ei</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">mein (main) — meu</div><div class=\"kurss-example\">dein (dain) — teu</div><div class=\"kurss-example\">sein (zain) — seu (dele) / ser</div><div class=\"kurss-example\">frei (frai) — livre</div><div class=\"kurss-example\">arbeiten (arbaiten) — trabalhar</div></div>\n            </section>\n            <section class=\"kurss-lesson-section\">\n              <h4>Notas de pronúncia da 2.ª aula</h4>\n              <ul class=\"kurss-summary-list\"><li>nas palavras ich, nicht, rechnen, zeichnen, o «ch» pronuncia-se de forma suave</li><li>nas palavras arbeiten e zeichnen, o «ei» pronuncia-se como «ai» (como em «pai»)</li><li>«sp» no início da palavra pronuncia-se como «chp»</li><li>no verbo tun, a letra «u» pronuncia-se longa</li></ul>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Resumo</h4>\n              <ul class=\"kurss-summary-list\"><li>uma consoante depois da vogal → muitas vezes vogal longa</li><li>duas ou mais consoantes → muitas vezes vogal curta</li><li>o h pode alongar a vogal</li><li>ie significa muitas vezes i longo</li><li>as vogais duplas são normalmente longas</li></ul>\n            </section>",
  "kurssConsonantsLesson": "\n            <h3>Consoantes e combinações de letras</h3>\n            <p class=\"kurss-lesson-intro\">Em alemão, algumas consoantes e combinações de letras pronunciam-se de forma diferente da que se escreve. Nesta aula estão os exemplos mais importantes para principiantes.</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Consoantes</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">das Rad (rāt) — roda</div><div class=\"kurss-example\">die Räder (rēder) — rodas</div><div class=\"kurss-example\">Bad (bāt) — banho / casa de banho</div><div class=\"kurss-example\">Bäder (bēder) — banhos / casas de banho</div></div>\n              <p>No fim da palavra, as consoantes muitas vezes não se pronunciam tal como se escrevem.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ch</h4>\n              <p>O «ch» pode pronunciar-se de forma suave ou forte. Em algumas palavras soa como um «h» aspirado e sibilante (como um sopro, entre «h» e «ch»), noutras mais próximo de um «k» gutural, semelhante ao «rr» do português europeu. Nas transcrições está escrito como «h».</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">rechnen (rehnen) — calcular</div><div class=\"kurss-example\">zeichnen (tsaihnen) — desenhar</div><div class=\"kurss-example\">nicht (niht) — não</div><div class=\"kurss-example\">schlecht (chleht) — mau</div><div class=\"kurss-example\">mich (mih) — me / a mim</div><div class=\"kurss-example\">dich (dih) — te / a ti</div><div class=\"kurss-example\">Strauch (chtrauh) — arbusto</div><div class=\"kurss-example\">noch (noh) — ainda</div><div class=\"kurss-example\">Nacht (naht) — noite</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>sch</h4>\n              <p>Em alemão, «sch» pronuncia-se como o «ch» português (como em «chave»).</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Schule (chūle) — escola</div><div class=\"kurss-example\">Schüler (chüler) — aluno</div><div class=\"kurss-example\">Schiff (chif) — navio</div><div class=\"kurss-example\">Schraube (chraube) — parafuso</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>sp e st no início da palavra</h4>\n              <p>No início de palavra ou de sílaba, «sp» pronuncia-se muitas vezes como «chp» e «st» como «cht».</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">spielen (chpīlen) — jogar / brincar / tocar</div><div class=\"kurss-example\">Sprung (chprung) — salto</div><div class=\"kurss-example\">stehen (chtēen) — estar de pé</div><div class=\"kurss-example\">Stall (chtal) — estábulo</div><div class=\"kurss-example\">Stand (chtant) — posição / banca (stand)</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>qu</h4>\n              <p>Em alemão, «qu» pronuncia-se normalmente como «kv».</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Qual (kvāl) — tormento / sofrimento</div><div class=\"kurss-example\">Quartier (kvartīr) — alojamento / bairro</div><div class=\"kurss-example\">quer (kvēr) — de través / transversalmente</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>s e z</h4>\n              <p>No início da palavra, o «s» soa muitas vezes como «z». A letra «z» em alemão soa como «ts».</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">sagen (zāguen) — dizer</div><div class=\"kurss-example\">singen (zinguen) — cantar</div><div class=\"kurss-example\">Rose (rōze) — rosa</div><div class=\"kurss-example\">Zahl (tsāl) — número</div><div class=\"kurss-example\">Zeit (tsait) — tempo</div><div class=\"kurss-example\">Zink (tsink) — zinco</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>v</h4>\n              <p>Em alemão, o «v» pronuncia-se muitas vezes como «f». Em palavras estrangeiras soa muitas vezes como o «v» português.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Vater (fāter) — pai</div><div class=\"kurss-example\">von (fon) — de</div><div class=\"kurss-example\">viel (fīl) — muito</div><div class=\"kurss-example\">vier (fīr) — quatro</div><div class=\"kurss-example\">Villa (vila) — vivenda / moradia</div><div class=\"kurss-example\">Klavier (klavīr) — piano</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>x e y</h4>\n              <p>O «x» pronuncia-se como «ks» (como em «táxi»). O «y» em algumas palavras pronuncia-se como «ü».</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Felix (fēliks) — Félix</div><div class=\"kurss-example\">Axt (akst) — machado</div><div class=\"kurss-example\">Mystik (müstik) — mística</div><div class=\"kurss-example\">Mythe (müte) — mito</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ß</h4>\n              <p>Em alemão, o «ß» pronuncia-se como um «s» surdo (como o «ss» de «passo»).</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Fuß (fūs) — pé</div><div class=\"kurss-example\">Füße (füsse) — pés</div><div class=\"kurss-example\">Grüße (grüsse) — cumprimentos</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Resumo</h4>\n              <ul class=\"kurss-summary-list\"><li>sch → ch (como em «chave»)</li><li>sp / st no início → chp / cht</li><li>qu → kv</li><li>z → ts</li><li>v muitas vezes → f</li><li>x → ks</li><li>ß → ss</li></ul>\n            </section>",
  "kurssVerbBasicsLesson": "\n            <h3>Bases dos verbos</h3>\n            <p class=\"kurss-lesson-intro\">Verbos da lição 1 e as suas formas (conjugação)</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Verbos</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">kommen — vir</div><div class=\"kurss-example\">gehen — ir</div><div class=\"kurss-example\">stehen — estar de pé</div><div class=\"kurss-example\">singen — cantar</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>kommen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich komme — eu venho</div><div class=\"kurss-example\">du kommst — tu vens</div><div class=\"kurss-example\">er kommt — ele vem</div><div class=\"kurss-example\">sie kommt — ela vem</div><div class=\"kurss-example\">wir kommen — nós vimos</div><div class=\"kurss-example\">ihr kommt — vocês vêm</div><div class=\"kurss-example\">sie kommen — eles / elas vêm</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>gehen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich gehe — eu vou</div><div class=\"kurss-example\">du gehst — tu vais</div><div class=\"kurss-example\">er geht — ele vai</div><div class=\"kurss-example\">sie geht — ela vai</div><div class=\"kurss-example\">wir gehen — nós vamos</div><div class=\"kurss-example\">ihr geht — vocês vão</div><div class=\"kurss-example\">sie gehen — eles / elas vão</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>stehen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich stehe — eu estou de pé</div><div class=\"kurss-example\">du stehst — tu estás de pé</div><div class=\"kurss-example\">er steht — ele está de pé</div><div class=\"kurss-example\">sie steht — ela está de pé</div><div class=\"kurss-example\">wir stehen — nós estamos de pé</div><div class=\"kurss-example\">ihr steht — vocês estão de pé</div><div class=\"kurss-example\">sie stehen — eles / elas estão de pé</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>singen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich singe — eu canto</div><div class=\"kurss-example\">du singst — tu cantas</div><div class=\"kurss-example\">er singt — ele canta</div><div class=\"kurss-example\">sie singt — ela canta</div><div class=\"kurss-example\">wir singen — nós cantamos</div><div class=\"kurss-example\">ihr singt — vocês cantam</div><div class=\"kurss-example\">sie singen — eles / elas cantam</div></div>\n            </section>\n            <section class=\"kurss-lesson-section\">\n              <h4>Verbos da lição 2</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">spielen — jogar</div><div class=\"kurss-example\">arbeiten — trabalhar</div><div class=\"kurss-example\">fragen — perguntar</div><div class=\"kurss-example\">antworten — responder</div><div class=\"kurss-example\">rechnen — calcular</div><div class=\"kurss-example\">zeichnen — desenhar</div><div class=\"kurss-example\">tun — fazer</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>spielen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich spiele — eu jogo</div><div class=\"kurss-example\">du spielst — tu jogas</div><div class=\"kurss-example\">er spielt — ele joga</div><div class=\"kurss-example\">sie spielt — ela joga</div><div class=\"kurss-example\">wir spielen — nós jogamos</div><div class=\"kurss-example\">ihr spielt — vocês jogam</div><div class=\"kurss-example\">sie spielen — eles / elas jogam</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>arbeiten</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich arbeite — eu trabalho</div><div class=\"kurss-example\">du arbeitest — tu trabalhas</div><div class=\"kurss-example\">er arbeitet — ele trabalha</div><div class=\"kurss-example\">sie arbeitet — ela trabalha</div><div class=\"kurss-example\">wir arbeiten — nós trabalhamos</div><div class=\"kurss-example\">ihr arbeitet — vocês trabalham</div><div class=\"kurss-example\">sie arbeiten — eles / elas trabalham</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>fragen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich frage — eu pergunto</div><div class=\"kurss-example\">du fragst — tu perguntas</div><div class=\"kurss-example\">er fragt — ele pergunta</div><div class=\"kurss-example\">sie fragt — ela pergunta</div><div class=\"kurss-example\">wir fragen — nós perguntamos</div><div class=\"kurss-example\">ihr fragt — vocês perguntam</div><div class=\"kurss-example\">sie fragen — eles / elas perguntam</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>antworten</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich antworte — eu respondo</div><div class=\"kurss-example\">du antwortest — tu respondes</div><div class=\"kurss-example\">er antwortet — ele responde</div><div class=\"kurss-example\">sie antwortet — ela responde</div><div class=\"kurss-example\">wir antworten — nós respondemos</div><div class=\"kurss-example\">ihr antwortet — vocês respondem</div><div class=\"kurss-example\">sie antworten — eles / elas respondem</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>rechnen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich rechne — eu calculo</div><div class=\"kurss-example\">du rechnest — tu calculas</div><div class=\"kurss-example\">er rechnet — ele calcula</div><div class=\"kurss-example\">sie rechnet — ela calcula</div><div class=\"kurss-example\">wir rechnen — nós calculamos</div><div class=\"kurss-example\">ihr rechnet — vocês calculam</div><div class=\"kurss-example\">sie rechnen — eles / elas calculam</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>zeichnen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich zeichne — eu desenho</div><div class=\"kurss-example\">du zeichnest — tu desenhas</div><div class=\"kurss-example\">er zeichnet — ele desenha</div><div class=\"kurss-example\">sie zeichnet — ela desenha</div><div class=\"kurss-example\">wir zeichnen — nós desenhamos</div><div class=\"kurss-example\">ihr zeichnet — vocês desenham</div><div class=\"kurss-example\">sie zeichnen — eles / elas desenham</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>tun</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich tue — eu faço</div><div class=\"kurss-example\">du tust — tu fazes</div><div class=\"kurss-example\">er tut — ele faz</div><div class=\"kurss-example\">sie tut — ela faz</div><div class=\"kurss-example\">wir tun — nós fazemos</div><div class=\"kurss-example\">ihr tut — vocês fazem</div><div class=\"kurss-example\">sie tun — eles / elas fazem</div></div>\n            </section>",
  "kurssSentenceStructureLesson": "\n            <h3>Estrutura da frase</h3>\n            <p class=\"kurss-lesson-intro\">Numa frase interrogativa, o verbo em alemão costuma ficar na primeira posição.</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Exemplos</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Du kommst. — Tu vens.</div><div class=\"kurss-example\">Kommst du? — Tu vens?</div><div class=\"kurss-example\">Er singt. — Ele canta.</div><div class=\"kurss-example\">Singt er? — Ele canta?</div><div class=\"kurss-example\">Stehst du? — Estás de pé?</div><div class=\"kurss-example\">Ja, ich stehe. — Sim, estou de pé.</div><div class=\"kurss-example\">Geht ihr? — Vocês vão?</div><div class=\"kurss-example\">Ja, wir gehen. — Sim, nós vamos.</div></div>\n            </section>\n            <section class=\"kurss-lesson-section\">\n              <h4>Perguntas com «was»</h4>\n              <p>Se a pergunta começa com uma palavra interrogativa, o verbo em alemão costuma ficar logo a seguir à palavra interrogativa.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Was tust du? — O que fazes?</div><div class=\"kurss-example\">Was tut er? — O que faz ele?</div><div class=\"kurss-example\">Was tut sie? — O que faz ela?</div><div class=\"kurss-example\">Was tun sie? — O que fazem eles / elas?</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Negação com «nicht»</h4>\n              <p>Se a negação «nicht» se refere ao verbo, em alemão costuma ficar depois do verbo.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Ich spiele nicht. — Eu não jogo.</div><div class=\"kurss-example\">Paul fragt nicht. — O Paul não pergunta.</div><div class=\"kurss-example\">Er kommt nicht. — Ele não vem.</div><div class=\"kurss-example\">Sie singen nicht. — Eles / elas não cantam.</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Frases da lição 2</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Spielst du? — Tu jogas?</div><div class=\"kurss-example\">Nein, ich spiele nicht, ich arbeite. — Não, eu não jogo, eu trabalho.</div><div class=\"kurss-example\">Paul fragt nicht, er arbeitet. — O Paul não pergunta, ele trabalha.</div><div class=\"kurss-example\">Arbeitest du? — Tu trabalhas?</div><div class=\"kurss-example\">Nein, ich arbeite nicht, ich singe. — Não, eu não trabalho, eu canto.</div><div class=\"kurss-example\">Was tut Paul? — O que faz o Paul?</div><div class=\"kurss-example\">Er spielt. — Ele joga.</div><div class=\"kurss-example\">Was tut Marie? — O que faz a Marie?</div><div class=\"kurss-example\">Sie singt. — Ela canta.</div><div class=\"kurss-example\">Paul spielt, aber Marie singt. — O Paul joga, mas a Marie canta.</div><div class=\"kurss-example\">Singt ihr? — Vocês cantam?</div><div class=\"kurss-example\">Nein, wir singen nicht, wir arbeiten. — Não, nós não cantamos, nós trabalhamos.</div><div class=\"kurss-example\">Was tun Paul und Marie? — O que fazem o Paul e a Marie?</div><div class=\"kurss-example\">Sie fragen. — Eles perguntam.</div><div class=\"kurss-example\">Sie antworten nicht. — Eles não respondem.</div><div class=\"kurss-example\">Wer arbeitet? — Quem trabalha?</div><div class=\"kurss-example\">Wir arbeiten. — Nós trabalhamos.</div><div class=\"kurss-example\">Wir rechnen und zeichnen. — Nós calculamos e desenhamos.</div><div class=\"kurss-example\">Sie kommen, sie fragen, sie antworten, sie arbeiten, sie spielen, sie singen, sie gehen. — Eles / elas vêm, perguntam, respondem, trabalham, jogam, cantam e vão.</div></div>\n            </section>",
  "kurssLesson2": "            <h3>Lição 2</h3>\n            <p class=\"kurss-lesson-intro\">Segunda lição: diálogos, palavras, pronúncia, gramática e tradução.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Diálogos / frases</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\">\n                  <div class=\"kurss-example\">Spielst du?<br>Nein, ich spiele nicht, ich arbeite.</div>\n                  <div class=\"kurss-example\">Paul fragt nicht, er arbeitet.</div>\n                  <div class=\"kurss-example\">Arbeitest du?<br>Nein, ich arbeite nicht, ich singe.</div>\n                  <div class=\"kurss-example\">Was tut Paul?<br>Er spielt.</div>\n                  <div class=\"kurss-example\">Was tut Marie?<br>Sie singt.</div>\n                  <div class=\"kurss-example\">Paul spielt, aber Marie singt.</div>\n                  <div class=\"kurss-example\">Singt ihr?<br>Nein, wir singen nicht, wir arbeiten.</div>\n                  <div class=\"kurss-example\">Was tun Paul und Marie?<br>Sie fragen.<br>Sie antworten nicht.</div>\n                  <div class=\"kurss-example\">Wer arbeitet?<br>Wir arbeiten.<br>Wir rechnen und zeichnen.</div>\n                  <div class=\"kurss-example\">Sie kommen, sie fragen, sie antworten, sie arbeiten, sie spielen, sie singen, sie gehen.</div>\n                </div>\n              </div>\n            </details>\n            <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Palavras</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\">\n                  <div class=\"kurss-example\">spielen — brincar; jogar</div>\n                  <div class=\"kurss-example\">nein — não</div>\n                  <div class=\"kurss-example\">nicht — não</div>\n                  <div class=\"kurss-example\">arbeiten — trabalhar</div>\n                  <div class=\"kurss-example\">fragen — perguntar</div>\n                  <div class=\"kurss-example\">was tut er? — o que faz ele?</div>\n                  <div class=\"kurss-example\">was tun sie? — o que fazem eles / elas?</div>\n                  <div class=\"kurss-example\">aber — mas</div>\n                  <div class=\"kurss-example\">antworten — responder</div>\n                  <div class=\"kurss-example\">rechnen — calcular, fazer contas</div>\n                  <div class=\"kurss-example\">zeichnen — desenhar</div>\n                  <div class=\"kurss-example\">Marie — Maria</div>\n                </div>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Pronúncia</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nas palavras ich, nicht, rechnen, zeichnen, o som ch pronuncia-se de forma suave, como um ch português muito leve e soprado, com a língua na posição do i.</div><div class=\"kurss-example\">Nas palavras arbeiten, zeichnen, o ditongo ei pronuncia-se aproximadamente como o ai português de «pai».</div><div class=\"kurss-example\">O grupo consonântico sp pronuncia-se como chp: spielen (chpílen).</div><div class=\"kurss-example\">No verbo tun, o u pronuncia-se longo em todas as pessoas.</div></div>\n              </div>\n            </details>\n<details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramática</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content lesson1-grammar-content\">\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>1</span>Terminações com e</h4>\n                  <div class=\"lesson1-grammar-note\">Se o radical do verbo terminar em t, d, chn, na conjugação aparece um e antes das terminações -st e -t.</div>\n                  <h5 class=\"lesson2-subtitle\">arbeiten</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich arbeite</div><div class=\"kurss-example\">du arbeitest</div><div class=\"kurss-example\">er arbeitet</div><div class=\"kurss-example\">sie arbeitet</div><div class=\"kurss-example\">wir arbeiten</div><div class=\"kurss-example\">ihr arbeitet</div><div class=\"kurss-example\">sie arbeiten</div></div>\n                  <h5 class=\"lesson2-subtitle\">rechnen</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich rechne</div><div class=\"kurss-example\">du rechnest</div><div class=\"kurss-example\">er rechnet</div><div class=\"kurss-example\">sie rechnet</div><div class=\"kurss-example\">wir rechnen</div><div class=\"kurss-example\">ihr rechnet</div><div class=\"kurss-example\">sie rechnen</div></div>\n                  <h5 class=\"lesson2-subtitle\">tun</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich tue</div><div class=\"kurss-example\">du tust</div><div class=\"kurss-example\">er tut</div><div class=\"kurss-example\">sie tut</div><div class=\"kurss-example\">wir tun</div><div class=\"kurss-example\">ihr tut</div><div class=\"kurss-example\">sie tun</div></div>\n                </section>\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>2</span>Palavra interrogativa</h4>\n                  <div class=\"lesson1-grammar-note\">Nas frases interrogativas que começam por uma palavra interrogativa, por exemplo: o quê? quem? qual? porquê? para quê? etc., o verbo vem logo a seguir à palavra interrogativa.</div>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Was tust du? — O que fazes?</div><div class=\"kurss-example\">Was tut er? — O que faz ele?</div><div class=\"kurss-example\">Was tut sie? — O que faz ela?</div><div class=\"kurss-example\">Was tun sie? — O que fazem eles / elas?</div></div>\n                </section>\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>3</span>Negação com nicht</h4>\n                  <div class=\"lesson1-grammar-note\">Se a negação nicht se refere ao verbo, a palavra negativa fica depois do verbo.</div>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Er kommt nicht. — Ele não vem.</div><div class=\"kurss-example\">Sie singen nicht. — Eles não cantam.</div></div>\n                </section>\n              </div>\n            </details>\n                                    <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Traduz</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-training-wrap\">\n                  <button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson2-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lição 2 · cartão de tradução\">\n                    <span class=\"lesson1-training-progress\">Lição 2 · Traduz: 1 / 15</span>\n                    <span class=\"lesson1-training-text\">Quem pergunta?</span>\n                  </button>\n                  <p class=\"lesson1-training-hint\">Clica no cartão para veres a tradução em alemão. Depois da resposta, o clique seguinte mostra o cartão seguinte.</p>\n                </div>\n              </div>\n            </details>",
  "kurssLesson6": "\n    <h3>Lição 6</h3>\n    <p class=\"kurss-lesson-intro\">Numerais, plural, umlauts e formas do plural dos substantivos.</p>\n\n    <details class=\"lesson1-accordion\" open>\n      <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Diálogos / frases</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hier liegt ein Bleistift.</div><div class=\"kurss-example\">Dort liegen einige Messer.</div><div class=\"kurss-example\">Edgar nimmt ein Messer, zwei Messer, drei Messer.</div><div class=\"kurss-example\">Er legt die Messer wieder hin.</div><div class=\"kurss-example\">Alle Messer sind scharf.</div><div class=\"kurss-example\">Dann nimmt er wieder ein Messer.</div><div class=\"kurss-example\">Er macht das Messer auf.</div><div class=\"kurss-example\">Er nimmt den Bleistift.</div><div class=\"kurss-example\">Er spitzt den Bleistift an.</div><div class=\"kurss-example\">Er legt das Messer hin.</div><div class=\"kurss-example\">Er setzt sich und zeichnet.</div><div class=\"kurss-example\">Was zeichnet er? Er zeichnet einen Schlüssel.</div><div class=\"kurss-example\">Gertrud zeichnet ein Fenster und eine Tafel.</div><div class=\"kurss-example\">Anna zeichnet einen Garten.</div><div class=\"kurss-example\">Hier liegen vier Löffel.</div><div class=\"kurss-example\">Dort liegen fünf Nadeln.</div><div class=\"kurss-example\">Gertrud kommt und zählt die Löffel: das ist ein Löffel; das sind zwei, drei, vier Löffel.</div><div class=\"kurss-example\">Anna zählt die Nadeln: das ist eine Nadel; das sind zwei, drei, vier, fünf Nadeln.</div><div class=\"kurss-example\">Wieviel Nadeln sind hier?</div><div class=\"kurss-example\">Hier ist eine Nadel.</div><div class=\"kurss-example\">Dort sind zwei, drei, vier Nadeln.</div><div class=\"kurss-example\">Fünf Schlüssel sind hier.</div><div class=\"kurss-example\">Sechs Löffel sind dort.</div><div class=\"kurss-example\">Was ist das?</div><div class=\"kurss-example\">Das ist ein Hammer. Das sind fünf Hämmer.</div><div class=\"kurss-example\">Das ist ein Deckel. Das sind sechs Deckel.</div><div class=\"kurss-example\">Das ist ein Eimer. Das sind sieben Eimer.</div><div class=\"kurss-example\">Das ist ein Teller. Das sind acht Teller.</div><div class=\"kurss-example\">Das ist ein Wagen. Das sind neun Wagen.</div><div class=\"kurss-example\">Das ist ein Schlitten. Das sind zehn Schlitten.</div><div class=\"kurss-example\">Wie sind die Dinge?</div><div class=\"kurss-example\">Der Hammer ist klein. Die Hämmer sind klein.</div><div class=\"kurss-example\">Der Deckel ist groß. Die Deckel sind groß.</div><div class=\"kurss-example\">Der Eimer ist voll. Die Eimer sind voll.</div><div class=\"kurss-example\">Der Teller ist leer. Die Teller sind leer.</div><div class=\"kurss-example\">Der Wagen ist schwer. Die Wagen sind schwer.</div><div class=\"kurss-example\">Der Schlitten ist leicht. Die Schlitten sind leicht.</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Palavras</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">liegt — encontra-se, está, está deitado</div><div class=\"kurss-example\">der Bleistift (blaichtift) — o lápis</div><div class=\"kurss-example\">einige (ainigue) — alguns</div><div class=\"kurss-example\">hinlegen — pousar</div><div class=\"kurss-example\">legt hin — pousa</div><div class=\"kurss-example\">wieder (víder) — outra vez, de novo</div><div class=\"kurss-example\">aufmachen — abrir</div><div class=\"kurss-example\">er macht auf — ele abre</div><div class=\"kurss-example\">anspitzen (ánchpitsen) — afiar</div><div class=\"kurss-example\">er spitzt an — ele afia</div><div class=\"kurss-example\">sich setzen — sentar-se</div><div class=\"kurss-example\">setzt sich — senta-se</div><div class=\"kurss-example\">der Schlüssel (chlússel) — a chave</div><div class=\"kurss-example\">das Fenster (fénster) — a janela</div><div class=\"kurss-example\">die Tafel (di táfel) — o quadro</div><div class=\"kurss-example\">der Garten — o jardim</div><div class=\"kurss-example\">der Löffel — a colher</div><div class=\"kurss-example\">zählen (tsêlen) — contar</div><div class=\"kurss-example\">die Nadel — a agulha</div><div class=\"kurss-example\">was ist das — o que é isto?</div><div class=\"kurss-example\">der Hammer — o martelo</div><div class=\"kurss-example\">die Hämmer — os martelos</div><div class=\"kurss-example\">der Deckel (dêr dékel) — a tampa</div><div class=\"kurss-example\">der Teller — o prato</div><div class=\"kurss-example\">der Wagen — a carroça</div><div class=\"kurss-example\">der Schlitten — o trenó</div><div class=\"kurss-example\">das Ding — a coisa</div><div class=\"kurss-example\">die Dinge — as coisas</div><div class=\"kurss-example\">wie sind die Dinge? — como são as coisas?</div><div class=\"kurss-example\">voll (fol) — cheio</div><div class=\"kurss-example\">leer (lêr) — vazio</div><div class=\"kurss-example\">schwer (chvêr) — pesado, difícil</div><div class=\"kurss-example\">leicht — leve</div><div class=\"kurss-example\">der Eimer — o balde</div><div class=\"kurss-example\">wieviel (vifíl) — quanto</div><div class=\"kurss-example\">wieviel Nadeln — quantas agulhas</div><div class=\"kurss-example\">hier (hir) — aqui</div><div class=\"kurss-example\">dort — ali</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Pronúncia</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">O ä é o umlaut da vogal a e pronuncia-se como um é aberto, breve ou longo.</div><div class=\"kurss-example\">Exemplos: das Mädchen (métchen), die Bänke (di bénke), der Vater (dêr fáter), die Väter (di féter).</div><div class=\"kurss-example\">O ü é o umlaut da vogal u. Para o pronunciar, arredondam-se bem os lábios e, com os lábios arredondados, tenta-se dizer i.</div><div class=\"kurss-example\">Exemplos: fünf, der Schlüssel (chlússel).</div><div class=\"kurss-example\">O ö pronuncia-se com os lábios arredondados, tentando dizer e: der Löffel.</div><div class=\"kurss-example\">Uma vogal dupla indica vogal longa: leer (lêr).</div><div class=\"kurss-example\">O ditongo eu pronuncia-se como o oi português: neun (nóin).</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramática</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content lesson1-grammar-content\">\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Gramática e explicações</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">No presente, o prefixo acentuado de um verbo composto separa-se do verbo e vai para o fim da frase.</div><div class=\"kurss-example\">Exemplos: hinlegen — er legt hin; aufmachen — er macht auf; anspitzen — er spitzt an.</div><div class=\"kurss-example\">O numeral um tem forma nos três géneros quando é usado com um substantivo: no masculino ein, no feminino eine, no neutro ein.</div><div class=\"kurss-example\">Exemplos: ein Schüler — um aluno; eine Schülerin — uma aluna; ein Kind — uma criança.</div><div class=\"kurss-example\">Numerais: eins, zwei, drei, vier (fir), fünf, sechs (zeks), sieben (zíben), acht, neun (nóin), zehn (tsên).</div><div class=\"kurss-example\">Em alemão, o verbo de ligação tem forma de singular e de plural: der Schüler ist klein; die Schüler sind klein.</div><div class=\"kurss-example\">Em português, o demonstrativo varia em género e número, como em este, esta, estes, estas, mas em alemão usa-se uma só forma: das.</div><div class=\"kurss-example\">Exemplos: este é um martelo — das ist ein Hammer; esta é uma agulha — das ist eine Nadel; estes são martelos — das sind Hämmer; estas são agulhas — das sind Nadeln.</div><div class=\"kurss-example\">Der Wagen — carroça e der Schlitten — trenó usam-se em alemão tanto no singular como no plural.</div><div class=\"kurss-example\">Os substantivos masculinos e neutros terminados em -er, -el, -en muitas vezes não recebem terminação no plural.</div><div class=\"kurss-example\">Exemplos: der Hammer — die Hämmer; der Garten — die Gärten; das Fenster — die Fenster; das Messer — die Messer.</div><div class=\"kurss-example\">Os substantivos femininos terminados em -el, -er recebem -n no plural.</div><div class=\"kurss-example\">Exemplos: die Nadel — die Nadeln; die Feder — die Federn.</div><div class=\"kurss-example\">Exceções: die Mutter (mãe) — die Mütter (mães); die Tochter (filha) — die Töchter (filhas).</div><div class=\"kurss-example\">O artigo indefinido não tem plural: das ist ein Wagen — das sind Wagen; das ist eine Nadel — das sind Nadeln.</div><div class=\"kurss-example\">Na frase declarativa, o predicado verbal ocupa o segundo lugar: er legt den Schlüssel hin; dann legt er den Schlüssel hin.</div></div></section>\n      </div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Traduz</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson6-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lição 6 · cartão de tradução\"><span class=\"lesson1-training-progress\">Lição 6 · Traduz: 1 / 21</span><span class=\"lesson1-training-text\">O Paul pega num lápis e desenha.</span></button><p class=\"lesson1-training-hint\">Clica no cartão para veres a tradução em alemão. Depois da resposta, o clique seguinte mostra o cartão seguinte.</p></div></div>\n    </details>\n  ",
  "kurssLesson5": "\n    <h3>Lição 5</h3>\n    <p class=\"kurss-lesson-intro\">Wen?, acusativo, sitzen, fragen e a terminação -in.</p>\n\n    <details class=\"lesson1-accordion\" open>\n      <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Diálogos / frases</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">Wer sitzt und fragt? Der Lehrer sitzt und fragt.</div>\n        <div class=\"kurss-example\">Wer steht und antwortet? Der Schüler steht und antwortet.</div>\n        <div class=\"kurss-example\">Wie antwortet der Schüler? Der Schüler antwortet gut.</div>\n        <div class=\"kurss-example\">Wen lobt der Lehrer? Der Lehrer lobt den Schüler.</div>\n        <div class=\"kurss-example\">Wie ist der Schüler? Der Schüler ist klein.</div>\n        <div class=\"kurss-example\">Ist der Schüler klein oder groß? Er ist klein.</div>\n        <div class=\"kurss-example\">Wen fragt die Lehrerin? Die Lehrerin fragt die Schülerin.</div>\n        <div class=\"kurss-example\">Wie antwortet die Schülerin? Die Schülerin antwortet schlecht.</div>\n        <div class=\"kurss-example\">Was tut die Lehrerin? Sie tadelt die Schülerin.</div>\n        <div class=\"kurss-example\">Die Schülerin ist nicht klein, sie ist groß.</div>\n        <div class=\"kurss-example\">Ein Kind spielt. Das Kind ist artig.</div>\n        <div class=\"kurss-example\">Die Mutter liebt das Kind. Der Vater lobt das Kind.</div>\n      </div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Palavras</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">sitzen (zítsen) — estar sentado</div>\n        <div class=\"kurss-example\">fragen (fráguen) — perguntar</div>\n        <div class=\"kurss-example\">der Lehrer (dêr lêrer) — o professor</div>\n        <div class=\"kurss-example\">gut (gut) — bem</div>\n        <div class=\"kurss-example\">wen (vên) — a quem</div>\n        <div class=\"kurss-example\">loben — elogiar</div>\n        <div class=\"kurss-example\">der Schüler (chúler) — o aluno</div>\n        <div class=\"kurss-example\">klein — pequeno</div>\n        <div class=\"kurss-example\">groß (grôs) — grande</div>\n        <div class=\"kurss-example\">die Lehrerin — a professora</div>\n        <div class=\"kurss-example\">die Schülerin — a aluna</div>\n        <div class=\"kurss-example\">schlecht (chlecht) — mal</div>\n        <div class=\"kurss-example\">tadeln — repreender</div>\n        <div class=\"kurss-example\">oder (ôder) — ou</div>\n        <div class=\"kurss-example\">das Kind (kint) — a criança</div>\n        <div class=\"kurss-example\">artig (ártich) — bem-comportado</div>\n        <div class=\"kurss-example\">die Mutter — a mãe</div>\n        <div class=\"kurss-example\">lieben (líben) — amar</div>\n        <div class=\"kurss-example\">der Vater (fáter) — o pai</div>\n      </div></div>\n    </details>\n\n        <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Pronúncia</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">tz é um z duplicado e pronuncia-se como o z alemão, ou seja, ts: sitzen (zítsen).</div>\n        <div class=\"kurss-example\">Nas palavras alemãs, o v pronuncia-se como f: der Vater (fáter).</div>\n        <div class=\"kurss-example\">O ß chama-se Eszett e pronuncia-se como o ss português de «passo»: groß (grôs), weiß (vais).</div>\n      </div></div>\n    </details>\n\n<details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramática</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content lesson1-grammar-content\">\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Nominativo e acusativo</h4><div class=\"lesson1-grammar-note\">Em português, o sujeito responde às perguntas quem? o quê?, e o complemento direto às perguntas quem? o quê? feitas depois do verbo.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Em alemão, no nominativo a pergunta é wer? para pessoas e was? para objetos.</div><div class=\"kurss-example\">No acusativo, a pergunta é wen? para pessoas e was? para objetos.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Mudança do artigo no acusativo</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nominativ: der Vater, die Mutter, das Kind.</div><div class=\"kurss-example\">Akkusativ: den Vater, die Mutter, das Kind.</div><div class=\"kurss-example\">Nominativ: der Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Akkusativ: den Federhalter, die Feder, das Messer.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">sitzen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich sitze</div><div class=\"kurss-example\">du sitzt</div><div class=\"kurss-example\">er/sie/es sitzt</div><div class=\"kurss-example\">wir sitzen</div><div class=\"kurss-example\">ihr sitzt</div><div class=\"kurss-example\">sie sitzen</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">fragen + acusativo</h4><div class=\"lesson1-grammar-note\">Em alemão, o verbo fragen rege o acusativo.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wen fragt der Lehrer?</div><div class=\"kurss-example\">Der Lehrer fragt den Schüler.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">A terminação -in</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Muitos substantivos femininos formam-se com a terminação -in.</div><div class=\"kurss-example\">die Lehrerin</div><div class=\"kurss-example\">die Schülerin</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Posição do verbo</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Na frase declarativa, o verbo ocupa o segundo lugar.</div><div class=\"kurss-example\">Dann geht das Mädchen hinaus und arbeitet.</div><div class=\"kurss-example\">Das Mädchen geht dann hinaus und arbeitet.</div></div></section>\n      </div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Traduz</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson5-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lição 5 · cartão de tradução\"><span class=\"lesson1-training-progress\">Lição 5 · Traduz: 1 / 16</span><span class=\"lesson1-training-text\">A quem ama o pai?</span></button><p class=\"lesson1-training-hint\">Clica no cartão para veres a tradução em alemão. Depois da resposta, o clique seguinte mostra o cartão seguinte.</p></div></div>\n    </details>\n  ",
  "kurssLesson4": "            <h3>Lição 4</h3>\n            <p class=\"kurss-lesson-intro\">Acusativo, nehmen, hinlegen, hinausgehen e adjetivos.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Diálogos / frases</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Paul kommt und nimmt einen Federhalter.</div><div class=\"kurss-example\">Er zeigt den Federhalter.</div><div class=\"kurss-example\">Er fragt: „Wie ist der Federhalter?“</div><div class=\"kurss-example\">Olga antwortet: „Der Federhalter ist schwarz.“</div><div class=\"kurss-example\">Ist der Federhalter weiß? Nein, der Federhalter ist nicht weiß, er ist schwarz.</div><div class=\"kurss-example\">Marie kommt und nimmt eine Feder.</div><div class=\"kurss-example\">Sie fragt: „Wie ist die Feder?“</div><div class=\"kurss-example\">Olga antwortet: „Die Feder ist spitz.“</div><div class=\"kurss-example\">Ist die Feder stumpf? Nein, die Feder ist nicht stumpf, sie ist spitz.</div><div class=\"kurss-example\">Was legt das Mädchen hin? Es legt die Feder hin.</div><div class=\"kurss-example\">Was nimmst du? Ich nehme ein Messer.</div><div class=\"kurss-example\">Wie ist das Messer? Das Messer ist scharf.</div><div class=\"kurss-example\">Ist das Messer stumpf? Nein, es ist nicht stumpf, es ist scharf.</div><div class=\"kurss-example\">Was legst du hin? Ich lege das Messer, die Feder und den Federhalter hin.</div><div class=\"kurss-example\">Dann gehe ich hinaus und arbeite.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Palavras</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">nehmen (nêmen) — pegar, tomar</div><div class=\"kurss-example\">er nimmt (nimt) — ele pega</div><div class=\"kurss-example\">der Federhalter (dêr fêderhalter) — a caneta</div><div class=\"kurss-example\">einen Federhalter — uma caneta</div><div class=\"kurss-example\">zeigen — mostrar</div><div class=\"kurss-example\">schwarz (chvarts) — preto</div><div class=\"kurss-example\">weiß (vais) — branco</div><div class=\"kurss-example\">die Feder (di fêder) — o aparo</div><div class=\"kurss-example\">eine Feder — um aparo</div><div class=\"kurss-example\">spitz (chpits) — pontiagudo, bicudo</div><div class=\"kurss-example\">hinlegen — pousar</div><div class=\"kurss-example\">legt hin — pousa</div><div class=\"kurss-example\">das Mädchen (métchen) — a rapariga</div><div class=\"kurss-example\">das Messer — a faca</div><div class=\"kurss-example\">ein Messer — uma faca</div><div class=\"kurss-example\">scharf — afiado</div><div class=\"kurss-example\">stumpf (chtumpf) — rombo</div><div class=\"kurss-example\">dann — depois, então</div><div class=\"kurss-example\">hinaus — para fora</div><div class=\"kurss-example\">hinausgehen — sair, ir lá para fora</div></div></div></details>\n                        <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Pronúncia</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">As terminações -en, -er, -el são átonas, por isso o e nestas terminações ouve-se pouco: kommen, nehmen, der Federhalter.</div><div class=\"kurss-example\">Em alemão, o h pode ser um som ou um sinal de que a vogal anterior é longa.</div><div class=\"kurss-example\">Se o h indica que a vogal é longa, não se pronuncia como som: nehmen (nêmen).</div><div class=\"kurss-example\">Se a vogal for seguida de uma só consoante, pronuncia-se longa: die (di) Feder (fêder), den (dên).</div></div></div></details>\n<details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramática</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Acusativo</h4><div class=\"lesson1-grammar-note\">No feminino e no neutro, o acusativo é igual ao nominativo. Só o masculino muda.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nominativ: der Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Akkusativ: den Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Nominativ: ein Federhalter, eine Feder, ein Messer.</div><div class=\"kurss-example\">Akkusativ: einen Federhalter, eine Feder, ein Messer.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>nehmen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich nehme</div><div class=\"kurss-example\">du nimmst</div><div class=\"kurss-example\">er/sie nimmt</div><div class=\"kurss-example\">wir nehmen</div><div class=\"kurss-example\">ihr nehmt</div><div class=\"kurss-example\">sie nehmen</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Pronomes</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">er — masculino</div><div class=\"kurss-example\">sie — feminino</div><div class=\"kurss-example\">es — neutro</div><div class=\"kurss-example\">plural — sie</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>Verbos separáveis</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">hinlegen → ich lege das Messer hin</div><div class=\"kurss-example\">hinausgehen → Marie geht hinaus</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>5</span>Adjetivos</h4><div class=\"lesson1-grammar-note\">Quando o adjetivo é predicativo na frase, não varia nem em género nem em número.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">der Federhalter ist klein</div><div class=\"kurss-example\">die Feder ist klein</div><div class=\"kurss-example\">das Messer ist klein</div><div class=\"kurss-example\">die Messer sind klein</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>6</span>Negação com nicht</h4><div class=\"lesson1-grammar-note\">Se nicht negar um adjetivo, fica antes da palavra negada.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">der Federhalter ist nicht weiß</div><div class=\"kurss-example\">das Messer ist nicht scharf</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>7</span>-chen / -lein</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Os substantivos terminados em -chen e -lein são neutros: das Mädchen.</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Traduz</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson4-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lição 4 · cartão de tradução\"><span class=\"lesson1-training-progress\">Lição 4 · Traduz: 1 / 16</span><span class=\"lesson1-training-text\">A rapariga pega numa caneta.</span></button><p class=\"lesson1-training-hint\">Clica no cartão para veres a tradução em alemão. Depois da resposta, o clique seguinte mostra o cartão seguinte.</p></div></div></details>",
  "kurssLesson3": "            <h3>Lição 3</h3>\n            <p class=\"kurss-lesson-intro\">Terceira lição: diálogos, palavras, pronúncia, gramática e tradução.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Diálogos / frases</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wer rechnet und zeichnet?<br>Wir rechnen und zeichnen.</div><div class=\"kurss-example\">Wer kommt?<br>Paul und Anna kommen.</div><div class=\"kurss-example\">Was steht hier?<br>Hier steht ein Tisch.</div><div class=\"kurss-example\">Was steht dort?<br>Dort steht eine Bank.</div><div class=\"kurss-example\">Was liegt hier?<br>Hier liegt ein Buch.</div><div class=\"kurss-example\">Was liegt dort?<br>Dort liegt ein Heft.</div><div class=\"kurss-example\">Was hängt hier?<br>Hier hängt ein Bild.</div><div class=\"kurss-example\">Was hängt dort?<br>Dort hängt eine Tafel.</div><div class=\"kurss-example\">Wie ist das Buch?<br>Das Buch ist dick.</div><div class=\"kurss-example\">Wie ist das Heft?<br>Das Heft ist dünn.</div><div class=\"kurss-example\">Wie ist die Bank?<br>Die Bank ist niedrig.</div><div class=\"kurss-example\">Wie ist der Tisch?<br>Der Tisch ist hoch.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Palavras</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">wer — quem</div><div class=\"kurss-example\">was — o quê</div><div class=\"kurss-example\">hier — aqui</div><div class=\"kurss-example\">dort — ali</div><div class=\"kurss-example\">der Tisch — a mesa</div><div class=\"kurss-example\">ein Tisch — uma mesa</div><div class=\"kurss-example\">die Bank — o banco</div><div class=\"kurss-example\">eine Bank — um banco</div><div class=\"kurss-example\">liegen — estar deitado</div><div class=\"kurss-example\">liegt hier ein Buch? — há / está aqui um livro?</div><div class=\"kurss-example\">das Buch — o livro</div><div class=\"kurss-example\">ein Buch — um livro</div><div class=\"kurss-example\">hängen — estar pendurado</div><div class=\"kurss-example\">das Bild — a imagem</div><div class=\"kurss-example\">ein Bild — uma imagem</div><div class=\"kurss-example\">die Tafel — o quadro</div><div class=\"kurss-example\">eine Tafel — um quadro</div><div class=\"kurss-example\">wie — como</div><div class=\"kurss-example\">ist — é</div><div class=\"kurss-example\">dick — grosso</div><div class=\"kurss-example\">das Heft — o caderno</div><div class=\"kurss-example\">ein Heft — um caderno</div><div class=\"kurss-example\">dünn — fino, magro</div><div class=\"kurss-example\">niedrig — baixo</div><div class=\"kurss-example\">hoch — alto</div></div></div></details>\n                        <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Pronúncia</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Em alemão, o som i longo escreve-se ie: liegen (líguen), hier (hir), wie (vi).</div><div class=\"kurss-example\">ck é um k duplo: dick (dikk).</div><div class=\"kurss-example\">Nos adjetivos e advérbios, a terminação -ig soa como um -ich suave: niedrig (nídrich).</div><div class=\"kurss-example\">Se a terminação -ig for seguida de e: -ige, o g pronuncia-se como um g nítido: niedrige (nídrigue) Bänke.</div></div></div></details>\n<details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramática</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Sujeito</h4><div class=\"lesson1-grammar-note\">Em alemão, o sujeito responde à pergunta wer? / was? e está no nominativo.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Com wer? pergunta-se por pessoas.</div><div class=\"kurss-example\">Com was? pergunta-se por objetos.</div><div class=\"kurss-example\">Wer singt? — Sie singt.</div><div class=\"kurss-example\">Was liegt hier? — Hier liegt ein Buch.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>Artigos</h4><div class=\"lesson1-grammar-note\">Em alemão, o substantivo tem 3 géneros: masculino, feminino e neutro. Antes do substantivo costuma haver uma pequena palavra chamada artigo. O género alemão nem sempre coincide com o português.</div><h5 class=\"lesson2-subtitle\">Artigo definido</h5><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">masculino — der</div><div class=\"kurss-example\">feminino — die</div><div class=\"kurss-example\">neutro — das</div><div class=\"kurss-example\">No plural, o artigo definido é die para os três géneros.</div><div class=\"kurss-example\">der Tisch — die Tische</div><div class=\"kurss-example\">die Bank — die Bänke</div><div class=\"kurss-example\">das Heft — die Hefte</div></div><h5 class=\"lesson2-subtitle\">Artigo indefinido</h5><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">masculino — ein</div><div class=\"kurss-example\">feminino — eine</div><div class=\"kurss-example\">neutro — ein</div><div class=\"kurss-example\">O artigo indefinido não tem plural.</div><div class=\"kurss-example\">ein Tisch — Tische</div><div class=\"kurss-example\">ein Heft — Hefte</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Nomes próprios</h4><div class=\"lesson1-grammar-note\">Em alemão, não se usa artigo antes dos nomes próprios.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hans spielt, aber Marie singt.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>Posição do verbo</h4><div class=\"lesson1-grammar-note\">Na frase declarativa, o verbo ocupa o segundo lugar.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hier hängt eine Karte.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>5</span>stehen / liegen / hängen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Em alemão, dos objetos que estão na vertical diz-se que «estão de pé»:<br>der Tisch steht<br>die Bank steht</div><div class=\"kurss-example\">Dos objetos em posição horizontal diz-se que «estão deitados»:<br>das Buch liegt<br>das Heft liegt</div><div class=\"kurss-example\">Os objetos também podem estar pendurados:<br>die Karte hängt<br>die Tafel hängt</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Traduz</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson3-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lição 3 · cartão de tradução\"><span class=\"lesson1-training-progress\">Lição 3 · Traduz: 1 / 22</span><span class=\"lesson1-training-text\">Fazes contas?</span></button><p class=\"lesson1-training-hint\">Clica no cartão para veres a tradução em alemão. Depois da resposta, o clique seguinte mostra o cartão seguinte.</p></div></div></details>",
  "kurssLesson7": "            <h3>Lição 7</h3>\n            <p class=\"kurss-lesson-intro\">Sétima lição: imperativo, forma de cortesia e plural.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Diálogos / frases</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hans, singe ein Lied! Was tust du? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans und Olga, singt ein Lied! Was tut ihr? Wir singen ein Lied.</div><div class=\"kurss-example\">Fräulein Müller, singen Sie, bitte, ein Lied! Was tun Sie? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans, zähle die Teller! Was tut Hans? Er zählt die Teller.</div><div class=\"kurss-example\">Hans und Olga, zählt die Teller! Was tun Hans und Olga? Sie zählen die Teller.</div><div class=\"kurss-example\">Fräulein Müller, zählen Sie, bitte, die Teller!</div><div class=\"kurss-example\">Hans, öffne das Fenster! Was tut Hans? Er öffnet das Fenster.</div><div class=\"kurss-example\">Hans und Olga, öffnet die Fenster! Was tun Hans und Olga? Sie öffnen die Fenster.</div><div class=\"kurss-example\">Fräulein Müller, öffnen Sie, bitte, alle Fenster!</div><div class=\"kurss-example\">Fräulein Müller öffnet alle Fenster.</div><div class=\"kurss-example\">Das ist der Spiegel. Das sind die Spiegel.</div><div class=\"kurss-example\">Das ist der Lappen. Das sind die Lappen.</div><div class=\"kurss-example\">Das ist der Spaten. Das sind die Spaten.</div><div class=\"kurss-example\">Das ist der Besen. Das sind die Besen.</div><div class=\"kurss-example\">Das ist die Schaufel. Das sind die Schaufeln.</div><div class=\"kurss-example\">Das ist die Schüssel. Das sind die Schüsseln.</div><div class=\"kurss-example\">Das ist das Zimmer. Das sind die Zimmer.</div><div class=\"kurss-example\">Das ist das Ufer. Das sind die Ufer.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Palavras</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">singen — cantar</div><div class=\"kurss-example\">singe — canta</div><div class=\"kurss-example\">singt — cantem (vocês)</div><div class=\"kurss-example\">singen Sie — cante / cantem (forma de cortesia)</div><div class=\"kurss-example\">das Lied (das lit) — a canção</div><div class=\"kurss-example\">Sie — o senhor / a senhora / os senhores</div><div class=\"kurss-example\">zählen — contar</div><div class=\"kurss-example\">das Fräulein (fróilain) — a menina</div><div class=\"kurss-example\">der Müller — o moleiro</div><div class=\"kurss-example\">öffnen — abrir</div><div class=\"kurss-example\">das Fenster (fénster) — a janela</div><div class=\"kurss-example\">alle — todos</div><div class=\"kurss-example\">der Spiegel (chpíguel) — o espelho</div><div class=\"kurss-example\">der Lappen — o pano, o trapo</div><div class=\"kurss-example\">der Spaten — a pá</div><div class=\"kurss-example\">der Besen — a vassoura</div><div class=\"kurss-example\">die Schaufel — a pazinha</div><div class=\"kurss-example\">die Schüssel — a tigela</div><div class=\"kurss-example\">das Zimmer — o quarto</div><div class=\"kurss-example\">das Ufer (úfer) — a margem</div></div></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Pronúncia</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">No início de palavra ou de sílaba, sp pronuncia-se como chp: der Spiegel (dêr chpíguel).</div><div class=\"kurss-example\">sch pronuncia-se como o ch português: die Schaufel (di cháufel), die Schüssel (di chússel).</div><div class=\"kurss-example\">O ditongo äu pronuncia-se como o oi português: das Fräulein (das fróilain).</div></div></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramática</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Imperativo</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">O imperativo na 2.ª pessoa do singular corresponde à 2.ª pessoa do singular do verbo sem a terminação pessoal -st, acrescentando-se a terminação -e.</div><div class=\"kurss-example\">Exemplos: antworte!, arbeite!, öffne!, zeichne!</div><div class=\"kurss-example\">Muitas vezes não se usa a terminação -e quando a forma do imperativo é monossilábica: geh!, steh!, komm!, tu!, sing!, frag!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>Imperativo no plural</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">A forma do imperativo na 2.ª pessoa do plural é igual à 2.ª pessoa do plural do presente, mas usa-se sem pronome.</div><div class=\"kurss-example\">Exemplos: antwortet!, arbeitet!, öffnet!, zeichnet!, geht!, steht!, tut!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Forma de cortesia com Sie</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">A forma de cortesia, que em português corresponde a o senhor / a senhora, é igual à 3.ª pessoa do plural. O pronome Sie escreve-se com maiúscula e vem depois do verbo.</div><div class=\"kurss-example\">Exemplos: antworten Sie!, arbeiten Sie!, öffnen Sie!, zeichnen Sie!, gehen Sie!, stehen Sie!, tun Sie!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>öffnen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">No verbo öffnen, para facilitar a pronúncia, na 2.ª e 3.ª pessoas do singular e na 2.ª pessoa do plural insere-se um e entre o radical e a terminação: du öffnest, er öffnet, ihr öffnet.</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Übung / Exercício</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson7-exercise-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lição 7 · cartão de exercício\"><span class=\"lesson1-training-progress\">Lição 7 · Übung: 1 / 16</span><span class=\"lesson1-training-text\">fragen — perguntar</span></button><p class=\"lesson1-training-hint\">Toca no cartão para veres as formas do imperativo.</p></div></div></details>",
  "kurssLesson1": "            <h3>Lição 1</h3>\n            <p class=\"kurss-lesson-intro\">Primeira lição: verbos no presente, vocabulário, pronúncia, gramática e tradução.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Verbos no presente</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-info\">Os verbos e a sua conjugação no presente.</div>\n                <div class=\"lesson1-verb-cards\">\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>kommen — vir</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>komme</strong><span>eu venho</span><span>du</span><strong>kommst</strong><span>tu vens</span><span>er / sie</span><strong>kommt</strong><span>ele / ela vem</span><span>wir</span><strong>kommen</strong><span>nós vimos</span><span>ihr</span><strong>kommt</strong><span>vocês vêm</span><span>sie / Sie</span><strong>kommen</strong><span>eles / os senhores vêm</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>gehen — ir</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>gehe</strong><span>eu vou</span><span>du</span><strong>gehst</strong><span>tu vais</span><span>er / sie</span><strong>geht</strong><span>ele / ela vai</span><span>wir</span><strong>gehen</strong><span>nós vamos</span><span>ihr</span><strong>geht</strong><span>vocês vão</span><span>sie / Sie</span><strong>gehen</strong><span>eles / os senhores vão</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>stehen — estar de pé</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>stehe</strong><span>eu estou de pé</span><span>du</span><strong>stehst</strong><span>tu estás de pé</span><span>er / sie</span><strong>steht</strong><span>ele / ela está de pé</span><span>wir</span><strong>stehen</strong><span>nós estamos de pé</span><span>ihr</span><strong>steht</strong><span>vocês estão de pé</span><span>sie / Sie</span><strong>stehen</strong><span>eles / os senhores estão de pé</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>singen — cantar</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>singe</strong><span>eu canto</span><span>du</span><strong>singst</strong><span>tu cantas</span><span>er / sie</span><strong>singt</strong><span>ele / ela canta</span><span>wir</span><strong>singen</strong><span>nós cantamos</span><span>ihr</span><strong>singt</strong><span>vocês cantam</span><span>sie / Sie</span><strong>singen</strong><span>eles / os senhores cantam</span></div>\n                  </article>\n                </div>\n                <section class=\"lesson1-block\">\n                  <h4>Exemplos</h4>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Stehst du?<br>Ja, ich stehe.</div><div class=\"kurss-example\">Steht Albert?<br>Ja, er steht.</div><div class=\"kurss-example\">Steht Marta?<br>Ja, sie steht.</div><div class=\"kurss-example\">Wer kommt und singt?<br>Albert und Marta kommen und singen.</div><div class=\"kurss-example\">Geht ihr?<br>Ja, wir gehen.</div><div class=\"kurss-example\">Wer steht und singt?<br>Albert und Marta stehen und singen.</div></div>\n                </section>\n              </div>\n            </details>\n            <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Palavras</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-info lesson1-vardini-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><span>A pronúncia aproximada das palavras é indicada entre parênteses com a ortografia portuguesa.<br>Isto aplica-se também às lições seguintes.</span></div>\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">wir (vir) — nós</div><div class=\"kurss-example\">Na palavra «wir», a letra i pronuncia-se longa.</div><div class=\"kurss-example\">kommen (kómen) — vir</div><div class=\"kurss-example\">gehen (guê-en) — ir</div><div class=\"kurss-example\">stehen (chtê-en) — estar de pé</div><div class=\"kurss-example\">singen (zínguen) — cantar</div><div class=\"kurss-example\">du (du) kommst — tu vens</div><div class=\"kurss-example\">er (êr) kommt — ele vem</div><div class=\"kurss-example\">sie (zi) kommt — ela vem</div><div class=\"kurss-example\">wer (vêr) — quem?</div><div class=\"kurss-example\">ja (iá) — sim</div></div>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Pronúncia</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">A pronúncia correta das palavras, escrita com a ortografia portuguesa, é indicada nas lições.</div><div class=\"kurss-example\">Wir (vir) — nós. Na palavra wir, o i pronuncia-se sempre longo.</div></div>\n              </div>\n            </details>\n<details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramática</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content lesson1-grammar-content\">\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>∞</span>Infinitivo</h4><div class=\"lesson1-grammar-note\">A forma básica do verbo. O infinitivo termina normalmente em -en.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">kommen</div><div class=\"kurss-example\">gehen</div><div class=\"kurss-example\">stehen</div><div class=\"kurss-example\">singen</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>♟</span>Terminações do presente</h4><div class=\"lesson1-ending-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><div class=\"lesson1-ending-info-body\"><p><strong>Retira <span class=\"lesson1-ending-accent\">-en</span> da forma básica do verbo e acrescenta a terminação.</strong></p><p>Exemplo: kommen → komm + terminação</p><div class=\"lesson1-ending-process\" aria-label=\"Como se formam as terminações do presente\"><div class=\"lesson1-ending-step\"><strong>kommen</strong><span>forma básica</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>retira <span class=\"lesson1-ending-accent\">-en</span></strong><span>fica o radical</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>komm</strong><span>radical</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>acrescenta a terminação</strong><span>e / st / t</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-results\"><div>komm + <span class=\"lesson1-ending-accent\">e</span> = <strong>komme</strong></div><div>komm + <span class=\"lesson1-ending-accent\">st</span> = <strong>kommst</strong></div><div>komm + <span class=\"lesson1-ending-accent\">t</span> = <strong>kommt</strong></div></div></div></div></div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich → -e</div><div class=\"kurss-example\">du → -st</div><div class=\"kurss-example\">er / sie → -t</div><div class=\"kurss-example\">wir → -en</div><div class=\"kurss-example\">ihr → -t</div><div class=\"kurss-example\">sie → -en</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>●</span>Exemplos</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich komme</div><div class=\"kurss-example\">du kommst</div><div class=\"kurss-example\">er kommt</div><div class=\"kurss-example\">wir kommen</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>?</span>Frases interrogativas</h4><div class=\"lesson1-grammar-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><span>Na frase interrogativa alemã, o verbo passa normalmente para o primeiro lugar.</span></div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Em português:<br>Tu vens.<br>Tu vens?</div><div class=\"kurss-example\">Em alemão:<br>Du kommst.<br>Kommst du?</div><div class=\"kurss-example\">du kommst — tu vens<br>kommst du? — vens?</div><div class=\"kurss-example\">er singt — ele canta<br>singt er? — ele canta?</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>♣</span>Distinção entre pessoas</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">er kommt — ele vem</div><div class=\"kurss-example\">sie kommt — ela vem</div><div class=\"kurss-example\">sie kommen — eles / elas vêm</div></div></section>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Traduz</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-training-wrap\">\n                  <button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson1-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lição 1 · cartão de treino\">\n                    <span class=\"lesson1-training-progress\">Lição 1 · Traduz: 1 / 11</span>\n                    <span class=\"lesson1-training-text\">Tu vens?</span>\n                  </button>\n                  <p class=\"lesson1-training-hint\">Clica no cartão para veres a tradução em alemão. Depois da resposta, o clique seguinte mostra o cartão seguinte.</p>\n                </div>\n              </div>\n            </details>"
};

